import json,os,subprocess,glob
O=os.path.join(os.path.dirname(os.path.abspath(__file__)),'..','out'); O=os.path.normpath(O)
def probe(p):
    r=subprocess.run(['ffprobe','-v','error','-show_entries','format=duration:stream=width,height,r_frame_rate','-of','json',p],capture_output=True,text=True)
    d=json.loads(r.stdout); s=d['streams'][0]
    return dict(duration_s=round(float(d['format'].get('duration',0)),3),width=s['width'],height=s['height'],fps=s['r_frame_rate'])
def kb(p): return round(os.path.getsize(p)/1024/1024,2)
