files=[]
for p in sorted(glob.glob(O+'/*.mp4'))+sorted(glob.glob(O+'/clips/*.mp4')):
    n=os.path.basename(p); info=probe(p); v='orig' if '-orig-' in n else 'brand'
    e=dict(file=os.path.relpath(p,O).replace(os.sep,'/'),**info,size_mb=kb(p),color_variant=v)
    if n.startswith('nivel-night'):
        e.update(kind='story',device='desktop' if info['width']==1920 else 'phone',steps=["02","(03 вставка)","04","05"])
    else:
        cid=n.split('-')[1]; e.update(kind='clip',source=cid,steps={"14203522":["04","05"],"14098235":["04"],"13075121":["02"]}[cid])
    e['encoding']='H.264 High, без B-кадров, GOP 6 (keyint_min 6, sc_threshold 0), faststart, без звука'
    files.append(e)
posters=[]
for p in sorted(glob.glob(O+'/posters/*.webp')):
    n=os.path.basename(p); posters.append(dict(file='posters/'+n,step=n[4:6],color_variant='orig' if '-orig-' in n else 'brand',width=1920 if n.endswith('1920.webp') else 960,size_kb=round(os.path.getsize(p)/1024,1),
      note='кадр 0 ролика (корпус) — заглушка, своего кадра 01 нет' if n.startswith('step01') else None))
